59	// Cooperatively stage the per-element meta-net phi weights into shared memory
60	// ONCE per block, then hand the shared pointers to the canonical
61	// sg15_phi_forward<H>. W1 is [H,2], b1/W2 are [H]. Removes the per-element
62	// re-read from GLOBAL inside the H-wide forward loop. NO math/signature change —
63	// the fn still takes const float* (single-sourced in algorithms/supergrok15.h).
64	template <int H>
65	__device__ __forceinline__ void sg15_stage_phi_weights(
66	    const float* __restrict__ W1, const float* __restrict__ b1,
67	    const float* __restrict__ W2,
68	    float* sW1, float* sb1, float* sW2
69	) {
70	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
71	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
72	    __syncthreads();
73	}
