100	template <typename ParamT, typename GradT, int UNROLL>
101	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
102	sg15_sweep_b_kernel(
103	    ParamT* param, float* exp_avg, float* exp_avg_sq,
104	    const GradT* grad, const float* mu,
105	    float gate_global, float alpha_base, float alpha_max,
106	    float lr, float beta1, float beta2, float eps, float wd,
107	    float bc1, float bc2, int64_t N
108	) {
109	    const int64_t stride = prim::grid_stride() * UNROLL;
110	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
111	    for (int64_t base = base0; base < N; base += stride) {
112	        #pragma unroll
113	        for (int u = 0; u < UNROLL; ++u) {
114	            const int64_t i = base + u;
115	            if (i < N) {
116	                SG_SANITIZE_GRAD_INPLACE(grad, i);
117	                sg15_sweep_b_step(param, exp_avg, exp_avg_sq, grad, mu,
118	                                  gate_global, alpha_base, alpha_max,
119	                                  lr, beta1, beta2, eps, wd, bc1, bc2, i);
120	            }
121	        }
122	    }
123	}
