243	// Full fused SG15 step: meta-net forward (sweep_a) + Adam update (sweep_b).
244	void launch_fused_supergrok15_full_step(
245	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
246	    torch::Tensor mu, torch::Tensor grad, torch::Tensor sharpness,
