278	void launch_sam_perturb(
279	    torch::Tensor param, torch::Tensor grad, float rho_over_norm
280	) {
281	    const int64_t N = param.numel();
282	    if (N == 0) return;
283	    auto stream = at::cuda::getCurrentCUDAStream().stream();
284	    const int block = SG_TUNED_BLOCK_SIZE;
285	    const int grid = static_cast<int>(
286	        std::min<int64_t>(65535, (N + block - 1) / block));
287	    AT_DISPATCH_FLOATING_TYPES_AND2(
288	        at::ScalarType::Half, at::ScalarType::BFloat16,
289	        param.scalar_type(), "sg15_sam_perturb", [&] {
290	            sg15_sam_perturb_kernel<scalar_t><<<grid, block, 0, stream>>>(
291	                param.data_ptr<scalar_t>(), grad.data_ptr<scalar_t>(),
292	                rho_over_norm, N);
293	            SG_LAUNCH_CHECK(stream);
294	        });
295	}
