201	inline float compute_sam_grad_norm_device_side(
202	    std::vector<torch::Tensor>& grads,
203	    size_t n_grads
204	) {
205	    torch::Device dev(torch::kCPU);
206	    for (size_t i = 0; i < n_grads; i++) {
207	        if (grads[i].defined() && grads[i].numel() > 0) {
208	            dev = grads[i].device();
209	            break;
210	        }
211	    }
212	    auto norm_sq = torch::zeros(
213	        {1}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
214	    for (size_t i = 0; i < n_grads; i++) {
215	        if (grads[i].defined() && grads[i].numel() > 0) {
216	            auto g_flat = grads[i].to(torch::kFloat32).reshape(-1);
217	            norm_sq.add_(g_flat.dot(g_flat));
218	        }
219	    }
220	    return std::sqrt(norm_sq.item<float>()) + 1e-12f;
221	}
